scwin.fn_SetCode = function() {
    //  기간 from~ to  셋팅	

	//----W-Craft WebSquare 변환 확인: cGetToday----//
    var vCurDate = cGetToday("yyyymmdd");
    edt_SDate_1.setValue("20000101");

	//----W-Craft WebSquare 변환 확인: cGetToday----//
    edt_EDate_1.setValue(cGetToday("yyyymmdd")); // 현재날짜

    edt_SDate_2.setValue("20000101");

	//----W-Craft WebSquare 변환 확인: cGetToday----//
    edt_EDate_2.setValue(cGetToday("yyyymmdd")); // 현재날짜

    edt_SDate_3.setValue("20000101");

	//----W-Craft WebSquare 변환 확인: cGetToday----//
    edt_EDate_3.setValue(cGetToday("yyyymmdd")); // 현재날짜
};
scwin.fn_radioDate = function() {

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    if (getObjectValue(rdo_checkDate) == "1") {

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
        scwin.pSDate = getObjectValue(edt_SDate_1);

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
        scwin.pEDate = getObjectValue(edt_EDate_1);

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    } else if (getObjectValue(rdo_checkDate) == "2") {

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
        scwin.pSDate = getObjectValue(edt_SDate_2);

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
        scwin.pEDate = getObjectValue(edt_EDate_2);

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    } else if (getObjectValue(rdo_checkDate) == "3") {

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
        scwin.pSDate = getObjectValue(edt_SDate_3);

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
        scwin.pEDate = getObjectValue(edt_EDate_3);
    }
};
scwin.fn_list_sync = function() {
    /*
    var url = "/ListedSearch.do?method=listPrelistingCondition&inputMessageId=LIST_KOSDAQ_NEW_PREEXAM" ;  

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    url +="&YYYYMMDD1=" + getObjectValue(edt_SDate);

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    url +="&YYYYMMDD2=" + getObjectValue(edt_EDate);

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    url +="&YYYYMMDD3=" + getObjectValue(edt_SDate2);

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    url +="&YYYYMMDD4=" + getObjectValue(edt_EDate2);

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    url +="&YYYYMMDD5=" + getObjectValue(edt_SDate3);

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    url +="&YYYYMMDD6=" + getObjectValue(edt_EDate3);
    url +="&PROCS_STAT_CD=" + cmd_procsStatCd.BindColVal;
    url +="&PUBOFR_TP="+   cmd_pubofrTpCd.BindColVal;
    url +="&INVSTG_COM_TP_CD="+  cmd_invstgComTpCd.BindColVal;
    */

    var cmbSTAT;

	//----W-Craft WebSquare 변환 확인: fn_getComboTextValue----//

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    if (getObjectValue(cmb_STAT) != "") cmbSTAT = fn_getComboTextValue(cmb_STAT);


	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    else cmbSTAT = getObjectValue(cmb_STAT);
    scwin.fn_radioDate();
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    url += "&method=listGeneral" + "&outputMessageId=LIST_KOSDAQ_NEW_PREEXAM" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.kosdaq.prelminvstgclm.condition" + "&{P}param01=" + scwin.pSDate + "&{P}param02=" + scwin.pEDate + "&{P}param03=" + getObjectValue(rdo_checkDate) + "&{P}param04=" + scwin.pSDate + "&{P}param05=" + scwin.pEDate + "&{P}param06=" + getObjectValue(rdo_checkDate) + "&{P}param07=" + scwin.pSDate + "&{P}param08=" + scwin.pEDate + "&{P}param09=" + getObjectValue(rdo_checkDate) + "&{P}param10=" + scwin.pSDate + "&{P}param11=" + scwin.pEDate + "&{P}param12=" + cmbSTAT + "&{P}param13=" + cmbSTAT + "&{P}param14=" + getObjectValue(cmb_PUBOFR_TP_CD) + "&{P}param15=" + getObjectValue(cmb_PUBOFR_TP_CD) + "&{P}param16=" + getObjectValue(cmb_PRELM_INVSTG_COM_TP_CD) + "&{P}param17=" + getObjectValue(cmb_PRELM_INVSTG_COM_TP_CD);
    dts_List.DataID = encodeURI(url);
    dts_List.reset();

	//----W-Craft WebSquare 변환 확인: ShowWin----//
    ShowWin(grd_List);
};
scwin.fn_list_all_sync = function() {
    var cmbSTAT;

	//----W-Craft WebSquare 변환 확인: fn_getComboTextValue----//

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    if (getObjectValue(cmb_STAT) != "") cmbSTAT = fn_getComboTextValue(cmb_STAT);


	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    else cmbSTAT = getObjectValue(cmb_STAT);
    scwin.fn_radioDate();
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    url += "&method=listGeneral" + "&outputMessageId=LIST_KOSDAQ_NEW_PREEXAM_ALL" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.select.kosdaq.prelminvstgclm.all.condition" + "&{P}param01=" + scwin.pSDate + "&{P}param02=" + scwin.pEDate + "&{P}param03=" + getObjectValue(rdo_checkDate) + "&{P}param04=" + scwin.pSDate + "&{P}param05=" + scwin.pEDate + "&{P}param06=" + getObjectValue(rdo_checkDate) + "&{P}param07=" + scwin.pSDate + "&{P}param08=" + scwin.pEDate + "&{P}param09=" + getObjectValue(rdo_checkDate) + "&{P}param10=" + scwin.pSDate + "&{P}param11=" + scwin.pEDate + "&{P}param12=" + cmbSTAT + "&{P}param13=" + cmbSTAT + "&{P}param14=" + getObjectValue(cmb_PUBOFR_TP_CD) + "&{P}param15=" + getObjectValue(cmb_PUBOFR_TP_CD) + "&{P}param16=" + getObjectValue(cmb_PRELM_INVSTG_COM_TP_CD) + "&{P}param17=" + getObjectValue(cmb_PRELM_INVSTG_COM_TP_CD);
    dts_List_All.DataID = encodeURI(url);
    dts_List_All.reset();

	//----W-Craft WebSquare 변환 확인: ShowWin----//
    ShowWin(grd_List_All);
};
scwin.fn_disable = function() {

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    if (getObjectValue(rdo_checkDate) == "2") {
        cmb_STAT.setValue("전체");
        cmb_STAT.setDisabled(true);
    } else {
        cmb_STAT.setDisabled(false);
    }
};
scwin.btn_Search_onclick = function(e) {
    if (chk_all.checked) {
        scwin.fn_list_all_sync();

	//----W-Craft WebSquare 변환 확인: showObj----//
        showObj(grd_List, false);

	//----W-Craft WebSquare 변환 확인: showObj----//
        showObj(grd_List_All, true);
    } else {
        scwin.fn_list_sync();

	//----W-Craft WebSquare 변환 확인: showObj----//
        showObj(grd_List, true);

	//----W-Craft WebSquare 변환 확인: showObj----//
        showObj(grd_List_All, false);
    }
    scwin.fn_disable();
};
scwin.btn_Excel_onclick = function(e) {

	//----W-Craft WebSquare 변환 확인: doLogSave----//
    doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07); // 엑셀
    if (chk_all.checked) {
        //grd_List_All.GridToExcel("예비심사청구조건검색현황", "", "8");

	//----W-Craft WebSquare 변환 확인: GridToOffice----//
        grd_List_All.GridToOffice("예비심사청구조건검색현황", "", 8, 0);
    } else {
        //grd_List.GridToExcel("예비심사청구조건검색현황", "", "8");

	//----W-Craft WebSquare 변환 확인: GridToOffice----//
        grd_List.GridToOffice("예비심사청구조건검색현황", "", 8, 0);
    }
};
scwin.chk_all_onclick = function(index, checked, value) {
    if (chk_all.checked) {
        scwin.fn_list_all_sync();

	//----W-Craft WebSquare 변환 확인: showObj----//
        showObj(grd_List, false);

	//----W-Craft WebSquare 변환 확인: showObj----//
        showObj(grd_List_All, true);
    } else {
        scwin.fn_list_sync();

	//----W-Craft WebSquare 변환 확인: showObj----//
        showObj(grd_List, true);

	//----W-Craft WebSquare 변환 확인: showObj----//
        showObj(grd_List_All, false);
    }
    scwin.fn_disable();
};
scwin.btn_Close_onclick = function(e) {

	//----W-Craft WebSquare 변환 확인: CloseFrame----//
    frame.CloseFrame();
};
scwin.dts_List_OnLoadError = function() {

	//----W-Craft WebSquare 변환 확인: alert_error----//
    alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {

	//----W-Craft WebSquare 변환 확인: FillGridHeaderTotalCnt----//
    FillGridHeaderTotalCnt(rowcount, panel_page);

	//----W-Craft WebSquare 변환 확인: CloseWin----//
    CloseWin(rowcount, grd_List);
};
scwin.dts_List_All_OnLoadError = function() {

	//----W-Craft WebSquare 변환 확인: alert_error----//
