};
scwin.rdo_checkDate_onclick = function(index, value) {
    scwin.fn_disable();
};
scwin.gform_onload = function() {

	//----W-Craft WebSquare 변환 확인: PanelToGroupBox----//
    PanelToGroupBox(panel_Top);
    scwin.fn_SetCode();
    scwin.fn_list_sync();

	//----W-Craft WebSquare 변환 확인: showObj----//
    showObj(grd_List_All, false);

	//----W-Craft WebSquare 변환 확인: showObj----//
    showObj(grd_List, true);
};

scwin.onpageload = function() {
};
